CREATE DATABASE IF NOT EXISTS learnloop CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE learnloop;
SET FOREIGN_KEY_CHECKS=0;
DROP TABLE IF EXISTS tbl_hourly_attendance;
DROP TABLE IF EXISTS tbl_timetable;
DROP TABLE IF EXISTS tbl_teacher_teaching;
DROP TABLE IF EXISTS tbl_batches;
DROP TABLE IF EXISTS tbl_attendance;
DROP TABLE IF EXISTS tbl_notes;
DROP TABLE IF EXISTS tbl_student_assignments;
DROP TABLE IF EXISTS tbl_assignments;
DROP TABLE IF EXISTS tbl_resume;
DROP TABLE IF EXISTS tbl_trs;
DROP TABLE IF EXISTS tbl_student;
DROP TABLE IF EXISTS tbl_admin;
DROP TABLE IF EXISTS tbl_leave_requests;
DROP TABLE IF EXISTS tbl_events;
SET FOREIGN_KEY_CHECKS=1;

CREATE TABLE tbl_events(id INT NOT NULL AUTO_INCREMENT,title VARCHAR(150) NOT NULL,date DATE NOT NULL,description TEXT NOT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,created_by VARCHAR(100) NOT NULL,PRIMARY KEY(id),INDEX(date)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE tbl_leave_requests(id INT NOT NULL AUTO_INCREMENT,username VARCHAR(100) NOT NULL,leave_date DATE NOT NULL,status ENUM('Pending','Approved','Rejected') NOT NULL DEFAULT 'Pending',PRIMARY KEY(id),INDEX(username),INDEX(leave_date)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE tbl_admin(id INT NOT NULL AUTO_INCREMENT,name VARCHAR(100) NOT NULL,username VARCHAR(100) NOT NULL UNIQUE,password VARCHAR(255) NOT NULL,PRIMARY KEY(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE tbl_batches(id INT NOT NULL AUTO_INCREMENT,batch_name VARCHAR(80) NOT NULL,course VARCHAR(80) NOT NULL,semester INT NOT NULL DEFAULT 1,active TINYINT(1) NOT NULL DEFAULT 1,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(id),UNIQUE KEY unique_batch(batch_name,course,semester)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE tbl_student(username VARCHAR(100) NOT NULL,reg_number VARCHAR(50) NULL,name VARCHAR(100) NOT NULL,age INT NOT NULL,password VARCHAR(255) NOT NULL,phone VARCHAR(20) NOT NULL,course VARCHAR(50) NOT NULL,batch_id INT NULL,approved TINYINT(1) NOT NULL DEFAULT 0,PRIMARY KEY(username),INDEX idx_student_batch(batch_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE tbl_trs(username VARCHAR(100) NOT NULL,name VARCHAR(100) NOT NULL,subject VARCHAR(100) NOT NULL DEFAULT '',password VARCHAR(255) NOT NULL,notes_file_path VARCHAR(255) NOT NULL DEFAULT '',semester INT NULL DEFAULT NULL,approved TINYINT(1) NOT NULL DEFAULT 1,PRIMARY KEY(username)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE tbl_user_settings(username VARCHAR(100) NOT NULL,role ENUM('student','teacher','admin') NOT NULL,theme ENUM('light','dark') NOT NULL DEFAULT 'light',profile_pic VARCHAR(255) NOT NULL DEFAULT '',email_notifications TINYINT(1) NOT NULL DEFAULT 1,assignment_notifications TINYINT(1) NOT NULL DEFAULT 1,attendance_notifications TINYINT(1) NOT NULL DEFAULT 1,show_academic_info TINYINT(1) NOT NULL DEFAULT 1,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,PRIMARY KEY(username,role)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE tbl_resume(id INT NOT NULL AUTO_INCREMENT,username VARCHAR(100) NOT NULL,resume_file VARCHAR(255) NOT NULL,Uploaded_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,approved TINYINT(1) NOT NULL DEFAULT 0,PRIMARY KEY(id),INDEX(username)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE tbl_notes(id INT NOT NULL AUTO_INCREMENT,teacher_username VARCHAR(100) NOT NULL,batch_id INT NULL,semester INT NULL,title VARCHAR(150) NOT NULL,subject VARCHAR(100) NOT NULL,file_path VARCHAR(255) NOT NULL,uploaded_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(id),INDEX(teacher_username),INDEX(batch_id),INDEX(subject),INDEX idx_notes_batch_semester(batch_id,semester)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE tbl_assignments(id INT NOT NULL AUTO_INCREMENT,teacher_username VARCHAR(100) NOT NULL,batch_id INT NULL,semester INT NULL,title VARCHAR(150) NOT NULL,subject VARCHAR(100) NOT NULL,description TEXT NOT NULL,due_date DATE NOT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(id),INDEX(teacher_username),INDEX(batch_id),INDEX(due_date),INDEX idx_assignments_batch_semester(batch_id,semester)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE tbl_student_assignments(id INT NOT NULL AUTO_INCREMENT,username VARCHAR(100) NOT NULL,assignment_id INT NULL,assignment_file_path VARCHAR(255) NOT NULL,subject VARCHAR(100) NOT NULL,teacher_username VARCHAR(100) NOT NULL,assignment_status TINYINT(1) NOT NULL DEFAULT 0,submitted_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(id),INDEX(username),INDEX(teacher_username),INDEX(assignment_id),UNIQUE KEY unique_student_assignment(username,assignment_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE tbl_attendance(id INT NOT NULL AUTO_INCREMENT,student_username VARCHAR(100) NOT NULL,attendance_date DATE NOT NULL,status ENUM('Present','Absent') NOT NULL DEFAULT 'Present',marked_by VARCHAR(100) NOT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(id),UNIQUE KEY unique_student_date(student_username,attendance_date),INDEX(student_username),INDEX(attendance_date),INDEX(marked_by)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE tbl_teacher_teaching(id INT NOT NULL AUTO_INCREMENT,teacher_username VARCHAR(100) NOT NULL,batch_id INT NOT NULL,semester INT NOT NULL,subject VARCHAR(100) NOT NULL,active TINYINT(1) NOT NULL DEFAULT 1,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(id),UNIQUE KEY unique_teacher_batch_sem_subject(teacher_username,batch_id,semester,subject),INDEX idx_teaching_teacher(teacher_username),INDEX idx_teaching_context(batch_id,semester),INDEX idx_teaching_subject(subject)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE tbl_timetable(id INT NOT NULL AUTO_INCREMENT,batch_id INT NOT NULL,teaching_assignment_id INT NULL,day_of_week TINYINT NOT NULL,hour_no TINYINT NOT NULL,subject VARCHAR(100) NOT NULL,teacher_username VARCHAR(100) NOT NULL,start_time TIME NOT NULL,end_time TIME NOT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(id),UNIQUE KEY unique_batch_day_hour(batch_id,day_of_week,hour_no),INDEX idx_tt_teacher(teacher_username),INDEX idx_tt_batch(batch_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE tbl_hourly_attendance(id INT NOT NULL AUTO_INCREMENT,timetable_id INT NOT NULL,student_username VARCHAR(100) NOT NULL,attendance_date DATE NOT NULL,status ENUM('Present','Absent') NOT NULL DEFAULT 'Present',marked_by VARCHAR(100) NOT NULL,marked_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,PRIMARY KEY(id),UNIQUE KEY unique_hourly_attendance(timetable_id,student_username,attendance_date),INDEX idx_ha_student_date(student_username,attendance_date),INDEX idx_ha_teacher(marked_by)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

